CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN CREATE ROLE backlog_runtime NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOBYPASSRLS; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TYPE project_role AS ENUM ('admin','triager','reporter');
CREATE TYPE ticket_status AS ENUM ('new','needs_clarification','in_progress','review','rework','done','deleted');
CREATE TYPE actor_kind AS ENUM ('user','agent','system');
CREATE TABLE tenants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), issuer text NOT NULL, subject text NOT NULL, email text, verified_email boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(issuer,subject));
CREATE TABLE tenant_memberships (tenant_id uuid NOT NULL REFERENCES tenants(id), user_id uuid NOT NULL REFERENCES users(id), is_owner boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,user_id));
CREATE TABLE projects (id uuid NOT NULL DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), project_key text NOT NULL UNIQUE, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,id), UNIQUE(id));
CREATE TABLE project_origins (tenant_id uuid NOT NULL, project_id uuid NOT NULL, origin text NOT NULL CHECK(origin ~ '^https?://[^/?#]+$'), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,project_id,origin), FOREIGN KEY(tenant_id,project_id) REFERENCES projects(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE project_memberships (tenant_id uuid NOT NULL, project_id uuid NOT NULL, user_id uuid NOT NULL REFERENCES users(id), role project_role NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,project_id,user_id), FOREIGN KEY(tenant_id,project_id) REFERENCES projects(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, project_id uuid, token_hash bytea NOT NULL UNIQUE, email text NOT NULL, role project_role, expires_at timestamptz NOT NULL, accepted_at timestamptz, accepted_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,project_id) REFERENCES projects(tenant_id,id));
CREATE TABLE pages (id uuid NOT NULL DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, project_id uuid NOT NULL, url_path text NOT NULL CHECK(url_path LIKE '/%'), url_pattern text, title text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,project_id,id), FOREIGN KEY(tenant_id,project_id) REFERENCES projects(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE tickets (id uuid NOT NULL DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, project_id uuid NOT NULL, page_id uuid, text text NOT NULL CHECK(length(text) BETWEEN 1 AND 4000), specification text NOT NULL DEFAULT '', priority smallint NOT NULL CHECK(priority BETWEEN 1 AND 5), due_date date, status ticket_status NOT NULL DEFAULT 'new', previous_status ticket_status, version bigint NOT NULL DEFAULT 1 CHECK(version > 0), anchor jsonb NOT NULL DEFAULT '{}', selection jsonb, context jsonb NOT NULL DEFAULT '{}', claimed_batch_id uuid, deleted_at timestamptz, deleted_by uuid, created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,project_id,id), UNIQUE(id), FOREIGN KEY(tenant_id,project_id) REFERENCES projects(tenant_id,id) ON DELETE CASCADE, FOREIGN KEY(tenant_id,project_id,page_id) REFERENCES pages(tenant_id,project_id,id));
CREATE TABLE ticket_events (id uuid NOT NULL DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, project_id uuid NOT NULL, ticket_id uuid NOT NULL, type text NOT NULL, actor_kind actor_kind NOT NULL, actor_id text NOT NULL, actor_name text NOT NULL, from_status ticket_status, to_status ticket_status, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,project_id,id), FOREIGN KEY(tenant_id,project_id,ticket_id) REFERENCES tickets(tenant_id,project_id,id) ON DELETE CASCADE);
CREATE TABLE ticket_attachments (id uuid NOT NULL DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, project_id uuid NOT NULL, ticket_id uuid NOT NULL, storage_key text NOT NULL UNIQUE, display_name text NOT NULL, media_type text NOT NULL, size_bytes bigint NOT NULL CHECK(size_bytes BETWEEN 1 AND 10485760), sha256 bytea NOT NULL, created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, PRIMARY KEY(tenant_id,project_id,id), FOREIGN KEY(tenant_id,project_id,ticket_id) REFERENCES tickets(tenant_id,project_id,id) ON DELETE CASCADE);
CREATE TABLE agent_tokens (id uuid NOT NULL DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, project_id uuid NOT NULL, prefix text NOT NULL UNIQUE, secret_hash bytea NOT NULL, scopes text[] NOT NULL, created_by uuid REFERENCES users(id), expires_at timestamptz, revoked_at timestamptz, last_used_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,project_id,id), FOREIGN KEY(tenant_id,project_id) REFERENCES projects(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE agent_batches (id uuid NOT NULL DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, project_id uuid NOT NULL, agent_token_id uuid, owner_subject text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz, PRIMARY KEY(tenant_id,project_id,id), FOREIGN KEY(tenant_id,project_id) REFERENCES projects(tenant_id,id) ON DELETE CASCADE);
ALTER TABLE tickets ADD CONSTRAINT tickets_claimed_batch_fk FOREIGN KEY(tenant_id,project_id,claimed_batch_id) REFERENCES agent_batches(tenant_id,project_id,id);
CREATE TABLE agent_batch_tickets (tenant_id uuid NOT NULL, project_id uuid NOT NULL, batch_id uuid NOT NULL, ticket_id uuid NOT NULL, completed_at timestamptz, PRIMARY KEY(tenant_id,project_id,batch_id,ticket_id), FOREIGN KEY(tenant_id,project_id,batch_id) REFERENCES agent_batches(tenant_id,project_id,id) ON DELETE CASCADE, FOREIGN KEY(tenant_id,project_id,ticket_id) REFERENCES tickets(tenant_id,project_id,id));
CREATE TABLE idempotency_keys (tenant_id uuid NOT NULL, project_id uuid NOT NULL, principal text NOT NULL, key text NOT NULL, request_hash bytea NOT NULL, status_code integer NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,project_id,principal,key), FOREIGN KEY(tenant_id,project_id) REFERENCES projects(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE storage_deletions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), storage_key text NOT NULL UNIQUE, attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE INDEX tickets_list_idx ON tickets(tenant_id,project_id,updated_at DESC,id DESC);
CREATE UNIQUE INDEX active_ticket_claim ON agent_batch_tickets(tenant_id,project_id,ticket_id) WHERE completed_at IS NULL;

DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['tenants','tenant_memberships','projects','project_origins','project_memberships','invitations','pages','tickets','ticket_events','ticket_attachments','agent_tokens','agent_batches','agent_batch_tickets','idempotency_keys'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); END LOOP; END $$;
CREATE POLICY tenant_scope ON tenants USING (id = NULLIF(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (id = NULLIF(current_setting('app.tenant_id',true),'')::uuid);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['tenant_memberships','projects','project_origins','project_memberships','invitations','pages','tickets','ticket_events','ticket_attachments','agent_tokens','agent_batches','agent_batch_tickets','idempotency_keys'] LOOP EXECUTE format('CREATE POLICY tenant_scope ON %I USING (tenant_id = NULLIF(current_setting(''app.tenant_id'',true),'''')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting(''app.tenant_id'',true),'''')::uuid)',t); END LOOP; END $$;
GRANT USAGE ON SCHEMA public TO backlog_runtime;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO backlog_runtime;
GRANT USAGE ON ALL SEQUENCES IN SCHEMA public TO backlog_runtime;
